// FUNCTIONS //

/**
* Initializes private instance properties.
*
* @private
* @param {PlotBase} plotBase - plotBase instance
* @param {Object} defaults - default property values
* @returns {PlotBase} plotBase instance
*/
function initializePrivateProperties( plotBase, defaults ) { // eslint-disable-line id-length
	var i;

	for ( i = 0; i < PRIVATE_PROPS.length; i++ ) {
		defineProperty( plotBase, PRIVATE_PROPS[ i ], {
			'configurable': false,
			'enumerable': false,
			'writable': true,
			'value': defaults[ PRIVATE_PROPS[ i ].substring( 1 ) ] || null
		});
	}
	return plotBase;
}


// MAIN //

/**
* Unicode table constructor.
*
* @constructor
* @throws {TypeError} data argument must be an object, an array of objects, an array of arrays, or a two-dimensional ndarray
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @returns {PlotBase} plotBase instance
*/
function PlotBase() {
	var options;
	var nargs;
	var opts;
	var keys;
	var self;
	var key;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof PlotBase ) ) {
		if ( nargs === 0 ) {
			return new PlotBase();
		}
		return new PlotBase( arguments[ 0 ] );
	}

	defineProperty( this, '_axisDataObjs', {
		'configurable': false,
		'enumerable': false,
		'writable': true,
		'value': [
			// X
			{
				'rawLabels': [],
				'normalizeLabels': [],
				'labelFormate': '%s',
				'axis': false,
				'ticsSpacing': 1,
				'position': 'default'
			},

			// Y
			{
				'rawLabels': [],
				'normalizeLabels': [],
				'labelFormate': '%s',
				'axis': false,
				'ticsSpacing': 1,
				'position': 'default'
			},

			// Z
			{
				'rawLabels': [],
				'normalizeLabels': [],
				'labelFormate': '%s',
				'axis': false,
				'ticsSpacing': 1,
				'position': 'default'
			},

			// W
			{
				'rawLabels': [],
				'normalizeLabels': [],
				'labelFormate': '%s',
				'axis': false,
				'ticsSpacing': 1,
				'position': 'default'
			}
		]
	});

	// Initialize private instance properties:
	initializePrivateProperties( this, defaults() );

	this._quiet = false;

	// Resolve input arguments...
	if ( nargs === 0 ) {
		options = {};
	} else {
		options = arguments[ 0 ];
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
	}
	// Extract provided options while ignoring any extraneous/unsupported options properties:
	opts = pick( options, OPTIONS_PROPS );

	debug( 'Creating an instance with the following configuration: %s.', JSON.stringify( opts ) );

	// Validate provided options by assigning values to plotBase properties...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		key = keys[ i ];
		this[ key ] = opts[ key ];
	}
	// Add event listeners:
	this.on( 'change', onChange );
	this.on( 'render', onRender );
	this.on( 'initialize', onInitalization );
	self = this;
	return this;

	/**
	* Callback invoked upon receiving a `change` event.
	*
	* @private
	*/
	function onChange() {
		/* eslint-disable no-underscore-dangle */
		debug( 'Received a change event.' );
		if ( self._autoRender ) {
			self.render();
		}
	}

	/**
	* Callback invoked upon receiving a `render` event.
	*
	* @private
	* @param {string} str - render string
	*/
	function onRender( str ) {
		console.log( str );
		debug( 'Received a render event.' );
	}

	/**
	* Callback invoked upon receiving a `render` event.
	*
	* @private
	* @param {string} table - rendered table
	*/
	function onInitalization() {
		debug( 'Received a render event.' );
		if ( self.autoInitialization ) {
			self.initialize();
		}
	}
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( PlotBase, EventEmitter );

/**
* Rendering mode.
*
* ## Notes
*
* -   If `true`, an instance automatically re-renders a table on each `change` event.
*
* @name autoRender
* @memberof UnicodeTable.prototype
* @type {boolean}
* @throws {TypeError} must be a boolean
* @default false
*
* @example
* var table = new UnicodeTable();
*
* table.autoRender = true;
*
* var v = table.autoRender;
* // returns true
*/
setReadWriteAccessor( PlotBase.prototype, 'autoRender', getAutoRender, setAutoRender );

